			        if (voDsBrdColDataList.getRowCount() > 0) voDsBrdColDataList.clearData();

			        // 추가 데이터 컬럼 초기화
			        mnBrdSeq = null;
			        voDmColDataParam.reset();

			        // 신규 생성여부(재조회시 조회수 카운트 제어용)
